script:
test("day 31 clamps in February 2026 then restores in March and clamps in April", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});

test("December 2027 start crosses into leap year 2028 and February ends on the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});

test("day 15 exists every month so dates stay on the 15th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});

test("a count of one returns the single due date one month after the start", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 1 }), ["2026-02-15"]);
});

test("a count of one on day 31 clamps February 2026 to the 28th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 1 }), ["2026-02-28"]);
});

test("day 1 exists in every following month", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-01", count: 3 }), ["2026-02-01", "2026-03-01", "2026-04-01"]);
});

test("day 27 stays on the 27th in non-leap February", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-27", count: 2 }), ["2026-02-27", "2026-03-27"]);
});

test("day 28 stays on the 28th in non-leap February and is not shortened", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-28", count: 2 }), ["2026-02-28", "2026-03-28"]);
});

test("day 29 clamps to February 28 in a non-leap year then restores to the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2025-01-29", count: 3 }), ["2025-02-28", "2025-03-29", "2025-04-29"]);
});

test("day 28 stays on the 28th in leap February and does not snap to the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-28", count: 2 }), ["2024-02-28", "2024-03-28"]);
});

test("day 29 exists in leap February 2024 and stays on the 29th afterward", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-29", count: 3 }), ["2024-02-29", "2024-03-29", "2024-04-29"]);
});

test("day 30 clamps leap February to the 29th then restores to the 30th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-01-30", count: 3 }), ["2024-02-29", "2024-03-30", "2024-04-30"]);
});

test("day 30 clamps non-leap February to the 28th then restores to the 30th not the 31st", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-30", count: 4 }), ["2026-02-28", "2026-03-30", "2026-04-30", "2026-05-30"]);
});

test("December start crosses the year and non-leap February clamps before March restores day 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-31", count: 3 }), ["2027-01-31", "2027-02-28", "2027-03-31"]);
});

test("a leap-day start keeps day 29 from the start date and clamps only the next non-leap February", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-02-29", count: 13 }), ["2024-03-29", "2024-04-29", "2024-05-29", "2024-06-29", "2024-07-29", "2024-08-29", "2024-09-29", "2024-10-29", "2024-11-29", "2024-12-29", "2025-01-29", "2025-02-28", "2025-03-29"]);
});

test("a 30-day month-end start keeps day 30 later and clamps only February", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-11-30", count: 4 }), ["2026-12-30", "2027-01-30", "2027-02-28", "2027-03-30"]);
});
